import{_ as t,o,c as n,a3 as a}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Contacts — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contacts — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/contacts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contacts — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/contacts"}]]},"headers":[],"relativePath":"user-guide/contacts.md","filePath":"user-guide/contacts.md","lastUpdated":1790810729000}'),s={name:"user-guide/contacts.md"};function r(i,e,l,c,d,g){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="contacts-—-user-guide" tabindex="-1">Contacts — User Guide <a class="header-anchor" href="#contacts-—-user-guide" aria-label="Permalink to &quot;Contacts — User Guide&quot;">​</a></h1><h2 id="who-can-use-contacts" tabindex="-1">Who can use Contacts <a class="header-anchor" href="#who-can-use-contacts" aria-label="Permalink to &quot;Who can use Contacts&quot;">​</a></h2><p>Your workspace must have the <strong>Contacts</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>export</code>, <code>import</code> as needed).</p><p>Without <strong>assign</strong>, you only see contacts assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Contacts</strong> from the sidebar under <strong>CRM</strong>.</p><ul><li>Search by name, email, phone, company (legacy string), or job title</li><li>Filter by company, assignee, lifecycle (<strong>On Boarded Clients</strong> / <strong>Off Boarded Clients</strong>), or toggle <strong>My Contacts</strong></li><li>When a contact is linked to a <a href="/user-guide/companies">Company</a>, the table shows the linked company name (falls back to the legacy company string)</li><li>KPI cards summarize total contacts, my contacts, unassigned, on boarded / off boarded clients, with email, and created this week</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted contact from the row menu — this trash filter is <strong>not</strong> the same as lifecycle On/Off Boarded</li><li><strong>Delete permanently</strong> (force delete) requires <code>contacts.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New contact</strong></li><li>Enter name (required) and optional email, phone, job title, lifecycle, and assignee</li><li>Optionally pick a <strong>Company</strong> (when the Companies module is installed and you can view companies). Selecting a Company links <code>company_id</code> and syncs the legacy company text to that organization name. Leaving the picker empty keeps any existing free-text company value on edit; clearing a previously linked Company removes the link</li><li>When Companies is installed and you have <strong>companies.create</strong>, use <strong>New</strong> next to the Company picker to create a company in a dialog — after save, that company is selected automatically</li><li>Save</li></ol><p>Edit from the row menu or the record page.</p><h2 id="related-sales-documents" tabindex="-1">Related sales documents <a class="header-anchor" href="#related-sales-documents" aria-label="Permalink to &quot;Related sales documents&quot;">​</a></h2><p>On a contact record page (when the matching module is installed and you have create permission), use:</p><ul><li><strong>New quotation</strong> → opens Quotation create with this contact preselected (<code>?contact=</code>; <code>?company=</code> when a company is linked)</li><li><strong>New invoice</strong> → same for Invoices</li><li><strong>New payment</strong> → same for Payments</li></ul><p>You finish the document on that module’s create page (quotations still require an opportunity).</p><h2 id="billing-hub-statement" tabindex="-1">Billing hub &amp; statement <a class="header-anchor" href="#billing-hub-statement" aria-label="Permalink to &quot;Billing hub &amp; statement&quot;">​</a></h2><p>When <strong>Invoices</strong> and/or <strong>Payments</strong> are installed and you can view them, the contact record shows a <strong>billing summary</strong>: invoice count, total invoiced, amount paid, and remaining balance (per currency when needed). Recent invoices, payments, and credit notes (when Credit Notes is installed) appear under related documents.</p><ul><li><strong>View all</strong> opens the Invoices or Payments list filtered to this contact (<code>/invoices?contact=</code> / <code>/payments?contact=</code>)</li><li><strong>Statement</strong> opens a period account statement (default: start of workspace year → today) with line history, opening/closing balance, totals, and PDF download when available</li></ul><p>List pages also accept <code>?contact=</code> and <code>?company=</code> deep links so you can share a filtered view without searching by name.</p><h2 id="related-opportunities-tickets-projects-documents" tabindex="-1">Related opportunities, tickets, projects &amp; documents <a class="header-anchor" href="#related-opportunities-tickets-projects-documents" aria-label="Permalink to &quot;Related opportunities, tickets, projects &amp; documents&quot;">​</a></h2><p>When those modules are installed and you can view them, the contact record also lists recent <strong>opportunities</strong>, <strong>help desk tickets</strong>, <strong>projects</strong>, and <strong>documents</strong> linked to this contact. <strong>View all</strong> opens the module list filtered with <code>?contact=</code>.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the contact</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, and delete/restore events</li></ul><h2 id="converting-a-lead-to-a-contact" tabindex="-1">Converting a Lead to a Contact <a class="header-anchor" href="#converting-a-lead-to-a-contact" aria-label="Permalink to &quot;Converting a Lead to a Contact&quot;">​</a></h2><p>When your workspace has both <strong>Leads</strong> and <strong>Contacts</strong> installed, converting a Lead (from the Lead record page) creates a linked Contact with lifecycle <strong>On Boarded Clients</strong>. If <strong>Companies</strong> is also installed and the lead has a company name, convert creates or reuses that Company and links it on the Contact. You can optionally create an <strong>Opportunity</strong> in the same step when Opportunities is installed. After conversion, the Lead record page shows <strong>View contact</strong> (and company / opportunity links when applicable).</p><h2 id="follow-ups-1-7-0" tabindex="-1">Follow-ups (1.7.0) <a class="header-anchor" href="#follow-ups-1-7-0" aria-label="Permalink to &quot;Follow-ups (1.7.0)&quot;">​</a></h2><p>Open a contact record page and use the <strong>Follow-ups</strong> section:</p><ol><li>Enter a <strong>Title</strong> and <strong>Due at</strong> (workspace <strong>Timezone</strong>, Settings → General), optional notes/assignee — requires <code>contacts.update</code></li><li><strong>Create follow-up</strong> saves it as <strong>pending</strong>. The contact&#39;s <strong>Next follow-up</strong> field (shown on the record header, table, and list sheet peek) always reflects the earliest pending follow-up</li><li><strong>Reschedule</strong> loads a follow-up back into the form so you can change its due date, title, or notes, then <strong>Save follow-up</strong></li><li><strong>Complete</strong> marks a follow-up done — it drops out of Next follow-up and no longer triggers due/overdue reminders</li></ol><p>When <strong>Calendar</strong> is installed, each contact&#39;s next pending follow-up is projected onto the assignee&#39;s calendar as a 1-hour event (source <strong>Contact</strong>); completing or clearing the last pending follow-up removes that projection automatically.</p><p><strong>Due / overdue reminders:</strong> the assignee (falling back to the contact&#39;s assignee) gets an in-app notification when a follow-up&#39;s due date arrives or has passed, sent by the same daily <code>crm:send-due-notifications</code> job that runs Lead, Task, and Contract reminders — one notification per follow-up per day.</p><h2 id="import-1-7-0" tabindex="-1">Import (1.7.0) <a class="header-anchor" href="#import-1-7-0" aria-label="Permalink to &quot;Import (1.7.0)&quot;">​</a></h2><p>Users with <strong>import</strong> can bulk-load contacts from <strong>CSV</strong> or <strong>XLSX</strong>:</p><ol><li>Open <strong>Import</strong> and download a sample template if needed (CSV or XLSX)</li><li>Upload a file (drag &amp; drop or browse)</li><li>Map spreadsheet columns to contact fields (<strong>Name</strong> is required; Email, Phone, Company, Job Title, Source, Lifecycle Status, and Assigned To are optional)</li><li>Choose unique fields (<strong>Email</strong> / <strong>Phone</strong>) and duplicate behavior (<strong>Skip</strong>, <strong>Update existing</strong>, or <strong>Keep duplicate</strong>)</li><li>Preview counts and validation errors (nothing is written yet)</li><li>Start the import — it runs in the background; watch progress until complete</li></ol><p><strong>Update existing</strong> also requires the <strong>update</strong> permission. Unlike Leads, Contact import has <strong>no equal-distribute assignment mode</strong> — an <strong>Assigned To</strong> column (matched by user email) sets the assignee directly, or rows default the same way manual create does.</p><p>Use <strong>Import history</strong> to review past imports, download the original file, <strong>failed_records.csv</strong>, or <strong>error_report.csv</strong>.</p><h2 id="export-1-7-0" tabindex="-1">Export (1.7.0) <a class="header-anchor" href="#export-1-7-0" aria-label="Permalink to &quot;Export (1.7.0)&quot;">​</a></h2><p>Users with <strong>export</strong> can download the current filtered set as <strong>CSV</strong> or <strong>XLSX</strong>, including lifecycle status, assignee, creator, and next follow-up.</p>',38)])])}const u=t(s,[["render",r]]);export{h as __pageData,u as default};
